(function(){'use strict';const dataNode=document.getElementById('site-data');let SITE={};try{SITE=JSON.parse((dataNode&&dataNode.textContent)||'{}');}catch(e){SITE={};}
const SEARCH_CFG=SITE.search||{};const rootPrefix=()=>document.documentElement.getAttribute('data-root')||'';const T=SITE.i18n||{};const t=(key,fallback)=>(T[key]!==undefined?T[key]:(fallback!==undefined?fallback:key));const HIST_KEY='ink-search-history';let engine=null;let worker=null;let workerReady=false;let detailsEntries=null;let records=[];let booted=false;let bootPromise=null;const filters={tags:[],categories:[],authors:[],year:[],pinned:false};let activeIndex=-1;let currentItems=[];let requestSeq=0;const el=(id)=>document.getElementById(id);const listTarget=()=>el('palette-results');const hintsTarget=()=>el('palette-hints');async function boot(){if(booted)return;if(bootPromise)return bootPromise;bootPromise=(async()=>{const site=window.InkSite;if(!site)return;const index=await site.Store.load();records=index.posts||[];engine=window.InkSearch.createEngine({synonyms:index.synonyms||{},stopwords:index.stopwords||[],fuzzy:(index.features&&index.features.fuzzy)!==false,pinyin:(index.features&&index.features.pinyin)!==false,max:SEARCH_CFG.max||40});engine.setPosts(records);let workerUrl=SITE.worker;try{const fresh=JSON.parse((document.getElementById('site-data')||{}).textContent||'{}');if(fresh.worker)workerUrl=fresh.worker;}catch(e){}
if(SEARCH_CFG.worker!==false&&workerUrl&&window.Worker){try{worker=new Worker(workerUrl);worker.onmessage=onWorkerMessage;worker.postMessage({type:'init',posts:records});}catch(e){worker=null;}}
booted=true;renderFacets();const loadDetails=async()=>{detailsEntries=await site.Store.allShards();if(worker&&workerReady)worker.postMessage({type:'details',details:detailsEntries});else engine.setDetails(detailsEntries);};if('requestIdleCallback'in window)requestIdleCallback(loadDetails,{timeout:4000});else setTimeout(loadDetails,1500);})();return bootPromise;}
function onWorkerMessage(event){const message=event.data||{};if(message.type==='ready'){workerReady=true;if(detailsEntries)worker.postMessage({type:'details',details:detailsEntries});return;}
if(message.type==='result'&&message.requestId===requestSeq){currentItems=message.items||[];renderResults(currentItems,message.total,message.terms,message.related);}}
let timer=null;function schedule(query,immediate){if(timer)clearTimeout(timer);const run=()=>execute(query);if(immediate)run();else timer=setTimeout(run,140);}
function execute(query){if(!engine)return;requestSeq+=1;const payload=Object.assign({},filters,{pinned:filters.pinned||undefined});if(worker&&workerReady){worker.postMessage({type:'query',query,filters:payload,requestId:requestSeq});return;}
const result=engine.search(query,payload);currentItems=result.items;renderResults(result.items,result.total,result.terms,result.total?[]:engine.relatedTags(8));}
function renderFacets(){document.querySelectorAll('[data-filters]').forEach((host)=>{const index=(window.InkSite&&window.InkSite.Store.index)||{};const facets=index.facets||{};const groups=[{key:'tags',label:t('site.tags','标签'),items:(facets.tags||[]).slice(0,8)},{key:'categories',label:t('site.categories','分类'),items:(facets.categories||[]).slice(0,6)},{key:'authors',label:t('site.authors','作者'),items:(facets.authors||[]).slice(0,4)},{key:'year',label:t('timeline.years','年份'),items:(facets.years||[]).slice(0,6).map((y)=>({name:y,slug:y}))}];const html=['<button type="button" class="facet" data-pinned>'+esc(t('label.pinned','置顶'))+'</button>'];groups.forEach((group)=>{group.items.forEach((item)=>{html.push('<button type="button" class="facet" data-group="'+group.key+'" data-value="'+
esc(item.name)+'">'+esc(item.name)+' <span>('+(item.count!==undefined?item.count:'')+')</span></button>');});});host.innerHTML=html.join('');});}
function bindFacets(host){host.querySelectorAll('[data-group]').forEach((btn)=>{btn.addEventListener('click',()=>{const group=btn.getAttribute('data-group');const value=btn.getAttribute('data-value');const list=filters[group];const at=list.indexOf(value);if(at>=0)list.splice(at,1);else list.push(value);btn.classList.toggle('is-on',at<0);schedule(currentQuery(),true);});});host.querySelectorAll('[data-pinned]').forEach((btn)=>{btn.addEventListener('click',()=>{filters.pinned=!filters.pinned;btn.classList.toggle('is-on',filters.pinned);schedule(currentQuery(),true);});});}
function renderResults(items,total,terms,related){const list=listTarget();const hints=hintsTarget();const count=document.querySelector('[data-search-count]');if(count)count.textContent=items.length?t('search.results','{n} 条结果').replace('{n}',String(total)):'';if(!items.length){currentItems=[];activeIndex=-1;if(list)list.innerHTML='';if(hints){hints.innerHTML='<p class="palette__empty">'+esc(t('search.empty','没有找到相关内容'))+'</p>'+'<p class="muted" style="text-align:center">'+esc(t('search.hint',''))+'</p>'+
((related&&related.length)?'<div class="hint-terms">'+related.map((tag)=>'<button type="button" class="facet" data-suggest="'+esc(tag.name)+'"># '+esc(tag.name)+'</button>').join('')+'</div>':'');bindSuggestions(hints);}
return;}
if(hints)hints.innerHTML='';if(list){list.innerHTML=items.map((item,index)=>resultRow(item,index)).join('');list.querySelectorAll('.result').forEach((row)=>{row.addEventListener('click',()=>navigate(row.getAttribute('data-url')));row.addEventListener('mouseenter',()=>setActive(Number(row.getAttribute('data-index'))));});activeIndex=-1;}
bindSuggestions(document);}
function resultRow(item,index){return'<li class="result" role="option" data-index="'+index+'" data-url="'+esc(rootPrefix()+item.url)+'">'+'<div class="result__head"><span class="result__title">'+item.titleHtml+'</span>'+'<span class="result__date">'+esc(String(item.date||'').slice(0,10))+'</span></div>'+'<p class="result__excerpt">'+item.excerptHtml+'</p>'+'<div class="result__terms">'+
(item.pinned?'<span class="chip chip--cat">'+esc(t('label.pinned','置顶'))+'</span>':'')+
(item.categories||[]).map((c)=>'<span class="chip chip--cat">'+esc(c)+'</span>').join('')+
(item.tags||[]).slice(0,3).map((x)=>'<span class="chip"># '+esc(x)+'</span>').join('')+'<span class="chip">'+(item.minutes||1)+' min</span>'+'</div></li>';}
function bindSuggestions(scope){scope.querySelectorAll('[data-suggest]').forEach((btn)=>{if(btn.dataset.bound)return;btn.dataset.bound='1';btn.addEventListener('click',()=>{const input=el('palette-input');if(input){input.value=btn.getAttribute('data-suggest');input.focus();}
schedule(btn.getAttribute('data-suggest'),true);});});}
function setActive(index){activeIndex=index;document.querySelectorAll('.result').forEach((row)=>{row.classList.toggle('is-active',Number(row.getAttribute('data-index'))===index);});}
function navigate(url,newTab){if(!url)return;const absolute=/^https?:/.test(url)?url:new URL(url,location.href).href;if(newTab){window.open(absolute,'_blank','noopener');return;}
if(window.InkNav)window.InkNav.go(absolute);else location.href=absolute;}
function readHistory(){try{return JSON.parse(localStorage.getItem(HIST_KEY)||'[]');}catch(e){return[];}}
function pushHistory(query){const value=String(query||'').trim();if(value.length<2)return;const list=readHistory().filter((item)=>item!==value);list.unshift(value);try{localStorage.setItem(HIST_KEY,JSON.stringify(list.slice(0,SEARCH_CFG.history||8)));}catch(e){}}
function showHistory(){const hints=hintsTarget();const list=listTarget();if(list)list.innerHTML='';if(!hints)return;const history=readHistory();if(!history.length){hints.innerHTML='<p class="palette__empty">'+esc(t('search.hint',''))+'</p>';return;}
hints.innerHTML='<div class="history-head"><span>'+esc(t('search.history','搜索历史'))+'</span>'+'<button type="button" data-clear-history>'+esc(t('search.reset','清空'))+'</button></div>'+'<div class="hint-terms">'+history.map((item)=>'<button type="button" class="facet" data-suggest="'+esc(item)+'">'+esc(item)+'</button>').join('')+'</div>';bindSuggestions(hints);const clear=hints.querySelector('[data-clear-history]');if(clear)clear.addEventListener('click',()=>{try{localStorage.removeItem(HIST_KEY);}catch(e){}
showHistory();});}
function currentQuery(){const input=el('palette-input');return(input&&input.value)||'';}
function openPalette(initialQuery){const palette=el('command-palette');if(!palette)return;palette.hidden=false;document.body.style.overflow='hidden';boot().then(()=>{renderFacets();const host=palette.querySelector('[data-filters]');if(host)bindFacets(host);syncFacetState(palette);const input=el('palette-input');if(input){if(initialQuery)input.value=initialQuery;input.focus();input.select();if(!input.value)showHistory();else schedule(input.value,true);}});}
function closePalette(){const palette=el('command-palette');if(palette)palette.hidden=true;document.body.style.overflow='';}
function initPalette(){const palette=el('command-palette');if(!palette)return;const input=el('palette-input');document.addEventListener('click',(event)=>{const btn=event.target&&event.target.closest?event.target.closest('[data-action="search"]'):null;if(!btn)return;event.preventDefault();openPalette();});if(input){input.addEventListener('input',()=>{if(!input.value){showHistory();return;}
schedule(input.value);});input.addEventListener('keydown',(event)=>{if(event.key==='ArrowDown'){event.preventDefault();if(!currentItems.length)return;setActive(Math.min(currentItems.length-1,activeIndex+1));scrollActiveIntoView();}else if(event.key==='ArrowUp'){event.preventDefault();if(!currentItems.length)return;setActive(Math.max(0,activeIndex-1));scrollActiveIntoView();}else if(event.key==='Enter'){event.preventDefault();if(activeIndex>=0&&currentItems[activeIndex]){pushHistory(input.value);navigate(rootPrefix()+currentItems[activeIndex].url,event.metaKey||event.ctrlKey);}else if(currentItems.length){pushHistory(input.value);navigate(rootPrefix()+currentItems[0].url,event.metaKey||event.ctrlKey);}}else if(event.key==='Escape'){closePalette();}});}
document.addEventListener('keydown',(event)=>{const key=event.key.toLowerCase();if((event.ctrlKey||event.metaKey)&&key==='k'){event.preventDefault();if(palette.hidden)openPalette();else closePalette();}else if(key==='/'&&!/input|textarea/i.test((event.target.tagName||''))&&palette.hidden){event.preventDefault();openPalette();}});}
function scrollActiveIntoView(){const row=document.querySelector('.result.is-active');if(row&&row.scrollIntoView)row.scrollIntoView({block:'nearest'});}
function syncFacetState(scope){scope.querySelectorAll('[data-group]').forEach((btn)=>{const group=btn.getAttribute('data-group');const value=btn.getAttribute('data-value');btn.classList.toggle('is-on',(filters[group]||[]).includes(value));});scope.querySelectorAll('[data-pinned]').forEach((btn)=>{btn.classList.toggle('is-on',Boolean(filters.pinned));});}
function esc(text){return window.InkSearch.escapeHtml(text);}
document.addEventListener('DOMContentLoaded',()=>{if(!SEARCH_CFG||SEARCH_CFG===false)return;initPalette();});window.InkSearchUI={open:openPalette,close:closePalette,boot};})();